import{_ as a,o as n,c as s,a3 as e}from"./chunks/framework.bvEHUNtb.js";const g=JSON.parse('{"title":"12 十二地支","description":"从月建、时辰与地支结构理解传统时间与空间的第二维坐标。","frontmatter":{"title":"12 十二地支","description":"从月建、时辰与地支结构理解传统时间与空间的第二维坐标。","category":"guide","aliases":["十二地支","地支"]},"headers":[],"relativePath":"topics/traditional-wisdom/time/twelve-earthly-branches.md","filePath":"topics/traditional-wisdom/time/twelve-earthly-branches.md","lastUpdated":1786982540000}'),l={name:"topics/traditional-wisdom/time/twelve-earthly-branches.md"};function p(i,t,d,c,r,o){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="_12-·-十二地支-时间坐标系的第二维" tabindex="-1">12 · 十二地支：时间坐标系的第二维 <a class="header-anchor" href="#_12-·-十二地支-时间坐标系的第二维" aria-label="Permalink to &quot;12 · 十二地支：时间坐标系的第二维&quot;">​</a></h1><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>本篇主要依据：</p><ul><li>《史记·律书》（司马迁，约前91年）</li><li>《淮南子·天文训》（刘安等，约前139年）</li><li>《礼记·月令》（先秦至汉，礼制文献）</li><li>《说文解字》（许慎，约公元100年）——字源考据</li><li>《三命通会》（万民英，明代）——藏干体系</li><li>《渊海子平》（徐升，宋代）——地支五行应用</li><li>《周礼》——十二时辰制度依据</li><li>考古参照：睡虎地秦简《日书》（约前217年），现存最早十二生肖与地支对应实物</li></ul><hr><h2 id="一、体系定位-在知识树中的坐标" tabindex="-1">一、体系定位：在知识树中的坐标 <a class="header-anchor" href="#一、体系定位-在知识树中的坐标" aria-label="Permalink to &quot;一、体系定位：在知识树中的坐标&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>十天干（太阳周期·10段·能量状态）</span></span>
<span class="line"><span>         +</span></span>
<span class="line"><span>十二地支（月亮轨道·12段·时空容器）  ←── 本篇</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>      六十甲子（10×12，完整时间编码）</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>  四柱·奇门·六爻·六壬·紫微·择日</span></span></code></pre></div><p>天干与地支的根本区别：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天干 = 天上的能量（阳·主动·状态描述）</span></span>
<span class="line"><span>地支 = 地上的容器（阴·被动·时空承载）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>天干问：此刻的能量是什么性质？</span></span>
<span class="line"><span>地支问：此刻的时空容器装着什么？</span></span></code></pre></div><p><strong>一句话定位：</strong><br> 十二地支是古人对月亮轨道与地球季节的十二段编码——<br> 它不只是&quot;第几月&quot;的标签，<br> 而是每个时空容器里，藏着什么五行能量、处于什么生命状态的完整描述。</p><h2 id="二、原典依据-四条核心文献" tabindex="-1">二、原典依据（四条核心文献） <a class="header-anchor" href="#二、原典依据-四条核心文献" aria-label="Permalink to &quot;二、原典依据（四条核心文献）&quot;">​</a></h2><h3 id="文献一-《史记·律书》——地支的天文本义" tabindex="-1">文献一：《史记·律书》——地支的天文本义 <a class="header-anchor" href="#文献一-《史记·律书》——地支的天文本义" aria-label="Permalink to &quot;文献一：《史记·律书》——地支的天文本义&quot;">​</a></h3><p>【原典】《史记》卷二十五·律书第三（司马迁，约前91年）</p><p>【原文节选】</p><blockquote><p>子者，滋也；滋者，言万物滋于下也。<br> 丑者，纽也；言阳气在上未降，万物厄纽未敢出也。<br> 寅者，言万物始生螾然也。<br> 卯者，言万物茂也。<br> 辰者，言万物之蜄也。<br> 巳者，言阳气之已尽也。<br> 午者，阴阳交，故曰午。<br> 未者，言万物皆成，有滋味也。<br> 申者，言阴用事，申贼万物，故曰申。<br> 酉者，万物之老也，故曰酉。<br> 戌者，言万物尽灭，故曰戌。<br> 亥者，该也，言阳气藏于下，故该也。</p></blockquote><p>这是现存最早对十二地支逐一训释的系统文献，揭示了每个地支对应的自然物候与阴阳消长状态。</p><h3 id="文献二-《淮南子·天文训》——地支与历法的完整对应" tabindex="-1">文献二：《淮南子·天文训》——地支与历法的完整对应 <a class="header-anchor" href="#文献二-《淮南子·天文训》——地支与历法的完整对应" aria-label="Permalink to &quot;文献二：《淮南子·天文训》——地支与历法的完整对应&quot;">​</a></h3><p>【原典】《淮南子》卷三·天文训（刘安等，约前139年）</p><p>【原文节选】</p><blockquote><p>寅，木也；卯，木也；辰，土也；巳，火也；午，火也；未，土也；申，金也；酉，金也；戌，土也；亥，水也；子，水也；丑，土也。</p></blockquote><p>这是地支五行归属的最早系统记载，同时《天文训》还详细记载了地支与月建（每月对应地支）的对应关系，是地支&quot;时间坐标&quot;功能的第一手文献。</p><h3 id="文献三-《礼记·月令》——地支与月份的制度化" tabindex="-1">文献三：《礼记·月令》——地支与月份的制度化 <a class="header-anchor" href="#文献三-《礼记·月令》——地支与月份的制度化" aria-label="Permalink to &quot;文献三：《礼记·月令》——地支与月份的制度化&quot;">​</a></h3><p>【原典】《礼记》第六篇·月令（先秦至汉）</p><p>《月令》以十二个月为框架，详细规定每月的天象、物候、政令与禁忌，是地支月建制度的礼制依据。其中&quot;孟春之月，日在营室，昏参中，旦尾中&quot;等记载，将地支月份与二十八星宿精确对应，是天文与历法融合的重要文献。</p><h3 id="文献四-考古实物——睡虎地秦简《日书》-约前217年" tabindex="-1">文献四：考古实物——睡虎地秦简《日书》（约前217年） <a class="header-anchor" href="#文献四-考古实物——睡虎地秦简《日书》-约前217年" aria-label="Permalink to &quot;文献四：考古实物——睡虎地秦简《日书》（约前217年）&quot;">​</a></h3><p>1975年湖北云梦睡虎地出土，其中《日书》甲种记载了十二地支与动物的对应关系，是现存最早的十二生肖与地支对应实物，证明这一体系在秦代已完全成型并广泛应用于日常择日。</p><h2 id="三、十二地支总览-完整对应表" tabindex="-1">三、十二地支总览：完整对应表 <a class="header-anchor" href="#三、十二地支总览-完整对应表" aria-label="Permalink to &quot;三、十二地支总览：完整对应表&quot;">​</a></h2><h3 id="_3-1-基础属性表" tabindex="-1">3.1 基础属性表 <a class="header-anchor" href="#_3-1-基础属性表" aria-label="Permalink to &quot;3.1 基础属性表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">地支</th><th style="text-align:center;">生肖</th><th style="text-align:center;">阴阳</th><th style="text-align:center;">五行</th><th style="text-align:center;">月份</th><th style="text-align:center;">时辰</th><th style="text-align:center;">方位</th><th style="text-align:center;">季节</th></tr></thead><tbody><tr><td style="text-align:center;">子</td><td style="text-align:center;">鼠</td><td style="text-align:center;">阳</td><td style="text-align:center;">水</td><td style="text-align:center;">十一月</td><td style="text-align:center;">23–01时</td><td style="text-align:center;">正北</td><td style="text-align:center;">仲冬</td></tr><tr><td style="text-align:center;">丑</td><td style="text-align:center;">牛</td><td style="text-align:center;">阴</td><td style="text-align:center;">土</td><td style="text-align:center;">十二月</td><td style="text-align:center;">01–03时</td><td style="text-align:center;">东北</td><td style="text-align:center;">季冬</td></tr><tr><td style="text-align:center;">寅</td><td style="text-align:center;">虎</td><td style="text-align:center;">阳</td><td style="text-align:center;">木</td><td style="text-align:center;">正月</td><td style="text-align:center;">03–05时</td><td style="text-align:center;">东北</td><td style="text-align:center;">孟春</td></tr><tr><td style="text-align:center;">卯</td><td style="text-align:center;">兔</td><td style="text-align:center;">阴</td><td style="text-align:center;">木</td><td style="text-align:center;">二月</td><td style="text-align:center;">05–07时</td><td style="text-align:center;">正东</td><td style="text-align:center;">仲春</td></tr><tr><td style="text-align:center;">辰</td><td style="text-align:center;">龙</td><td style="text-align:center;">阳</td><td style="text-align:center;">土</td><td style="text-align:center;">三月</td><td style="text-align:center;">07–09时</td><td style="text-align:center;">东南</td><td style="text-align:center;">季春</td></tr><tr><td style="text-align:center;">巳</td><td style="text-align:center;">蛇</td><td style="text-align:center;">阴</td><td style="text-align:center;">火</td><td style="text-align:center;">四月</td><td style="text-align:center;">09–11时</td><td style="text-align:center;">东南</td><td style="text-align:center;">孟夏</td></tr><tr><td style="text-align:center;">午</td><td style="text-align:center;">马</td><td style="text-align:center;">阳</td><td style="text-align:center;">火</td><td style="text-align:center;">五月</td><td style="text-align:center;">11–13时</td><td style="text-align:center;">正南</td><td style="text-align:center;">仲夏</td></tr><tr><td style="text-align:center;">未</td><td style="text-align:center;">羊</td><td style="text-align:center;">阴</td><td style="text-align:center;">土</td><td style="text-align:center;">六月</td><td style="text-align:center;">13–15时</td><td style="text-align:center;">西南</td><td style="text-align:center;">季夏</td></tr><tr><td style="text-align:center;">申</td><td style="text-align:center;">猴</td><td style="text-align:center;">阳</td><td style="text-align:center;">金</td><td style="text-align:center;">七月</td><td style="text-align:center;">15–17时</td><td style="text-align:center;">西南</td><td style="text-align:center;">孟秋</td></tr><tr><td style="text-align:center;">酉</td><td style="text-align:center;">鸡</td><td style="text-align:center;">阴</td><td style="text-align:center;">金</td><td style="text-align:center;">八月</td><td style="text-align:center;">17–19时</td><td style="text-align:center;">正西</td><td style="text-align:center;">仲秋</td></tr><tr><td style="text-align:center;">戌</td><td style="text-align:center;">狗</td><td style="text-align:center;">阳</td><td style="text-align:center;">土</td><td style="text-align:center;">九月</td><td style="text-align:center;">19–21时</td><td style="text-align:center;">西北</td><td style="text-align:center;">季秋</td></tr><tr><td style="text-align:center;">亥</td><td style="text-align:center;">猪</td><td style="text-align:center;">阴</td><td style="text-align:center;">水</td><td style="text-align:center;">十月</td><td style="text-align:center;">21–23时</td><td style="text-align:center;">西北</td><td style="text-align:center;">孟冬</td></tr></tbody></table><p>【说明】月份以农历月建为准（寅月为正月，即建寅）；时辰为地方真太阳时。</p><h3 id="_3-2-象意详解-每个地支的-状态描述" tabindex="-1">3.2 象意详解：每个地支的&quot;状态描述&quot; <a class="header-anchor" href="#_3-2-象意详解-每个地支的-状态描述" aria-label="Permalink to &quot;3.2 象意详解：每个地支的&quot;状态描述&quot;&quot;">​</a></h3><p>与天干一样，理解地支最重要的是建立画面感，而不是死记属性。<br> 依据《史记·律书》逐一解读：</p><h4 id="🌊-子-zi-·-阳水-·-十一月-·-仲冬" tabindex="-1">🌊 子（zǐ）· 阳水 · 十一月 · 仲冬 <a class="header-anchor" href="#🌊-子-zi-·-阳水-·-十一月-·-仲冬" aria-label="Permalink to &quot;🌊 子（zǐ）· 阳水 · 十一月 · 仲冬&quot;">​</a></h4><p>【字形】象婴儿在襁褓中，头大身小<br> 【原文】&quot;子者，滋也；言万物滋于下也。&quot;（《史记·律书》）<br> 【状态】一阳初生，万物在地下悄然滋生，外表寂静，内部涌动</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>子 = 冬至时节</span></span>
<span class="line"><span>  = 最黑暗的夜晚，但一阳已生</span></span>
<span class="line"><span>  = 表面是极寒，内部是新生命的起点</span></span>
<span class="line"><span>  = 深夜子时，万籁俱寂，但生机已在暗中萌动</span></span></code></pre></div><p>关键：子是水，但是阳水——不是静止的水，是地下涌动的泉源。</p><h4 id="🌱-丑-chou-·-阴土-·-十二月-·-季冬" tabindex="-1">🌱 丑（chǒu）· 阴土 · 十二月 · 季冬 <a class="header-anchor" href="#🌱-丑-chou-·-阴土-·-十二月-·-季冬" aria-label="Permalink to &quot;🌱 丑（chǒu）· 阴土 · 十二月 · 季冬&quot;">​</a></h4><p>【字形】象手指弯曲，有纽结之形<br> 【原文】&quot;丑者，纽也；言阳气在上未降，万物厄纽未敢出也。&quot;（《史记·律书》）<br> 【状态】阳气已生但尚未下降，万物被束缚，蓄势待发</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>丑 = 严冬腊月</span></span>
<span class="line"><span>  = 种子在土里，已经感受到阳气，但还不敢破土</span></span>
<span class="line"><span>  = 被压制的力量，内部张力极大</span></span>
<span class="line"><span>  = 丑土 = 冻土，藏而不发</span></span></code></pre></div><p>丑是四库之一（辰戌丑未），是金的墓库——冬末的冻土，封存着金的能量。</p><h4 id="🐯-寅-yin-·-阳木-·-正月-·-孟春" tabindex="-1">🐯 寅（yín）· 阳木 · 正月 · 孟春 <a class="header-anchor" href="#🐯-寅-yin-·-阳木-·-正月-·-孟春" aria-label="Permalink to &quot;🐯 寅（yín）· 阳木 · 正月 · 孟春&quot;">​</a></h4><p>【字形】象两手捧物，有生发之意<br> 【原文】&quot;寅者，言万物始生螾然也。&quot;（《史记·律书》）——螾然，蠕动生发之状<br> 【状态】万物开始蠕动萌发，生命力破土而出</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>寅 = 立春时节，正月建寅</span></span>
<span class="line"><span>  = 第一声春雷，万物惊蛰前的蠕动</span></span>
<span class="line"><span>  = 生命力最旺盛的起点</span></span>
<span class="line"><span>  = 寅时（凌晨3–5点）= 黎明前最后的黑暗，但生机已无法遏制</span></span></code></pre></div><p>寅是奇门遁甲的重要方位，也是四柱中&quot;长生&quot;的关键地支之一。</p><h4 id="🌿-卯-mao-·-阴木-·-二月-·-仲春" tabindex="-1">🌿 卯（mǎo）· 阴木 · 二月 · 仲春 <a class="header-anchor" href="#🌿-卯-mao-·-阴木-·-二月-·-仲春" aria-label="Permalink to &quot;🌿 卯（mǎo）· 阴木 · 二月 · 仲春&quot;">​</a></h4><p>【字形】象门开两扇，有开放之意<br> 【原文】&quot;卯者，言万物茂也。&quot;（《史记·律书》）<br> 【状态】万物茂盛生长，门户大开，欣欣向荣</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卯 = 春分时节</span></span>
<span class="line"><span>  = 昼夜等长，阴阳平衡的节点</span></span>
<span class="line"><span>  = 万物全面生长，生机最旺</span></span>
<span class="line"><span>  = 卯时（5–7点）= 日出，一天的开始</span></span></code></pre></div><p>卯是木的旺地——木在卯月达到最旺状态（帝旺）。</p><h4 id="🐉-辰-chen-·-阳土-·-三月-·-季春" tabindex="-1">🐉 辰（chén）· 阳土 · 三月 · 季春 <a class="header-anchor" href="#🐉-辰-chen-·-阳土-·-三月-·-季春" aria-label="Permalink to &quot;🐉 辰（chén）· 阳土 · 三月 · 季春&quot;">​</a></h4><p>【字形】象蛟龙之形，有震动之意<br> 【原文】&quot;辰者，言万物之蜄也。&quot;（《史记·律书》）——蜄，震动生长<br> 【状态】春末，万物震动生长到极致，即将转入夏季</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>辰 = 清明谷雨时节</span></span>
<span class="line"><span>  = 春雨充沛，万物疯长的最后阶段</span></span>
<span class="line"><span>  = 辰土 = 湿土，含水量最高的土</span></span>
<span class="line"><span>  = 龙行雨施，生机勃发</span></span></code></pre></div><p>辰是四库之一，是水的墓库——春末的湿土，储藏着水的能量。</p><h4 id="🐍-巳-si-·-阴火-·-四月-·-孟夏" tabindex="-1">🐍 巳（sì）· 阴火 · 四月 · 孟夏 <a class="header-anchor" href="#🐍-巳-si-·-阴火-·-四月-·-孟夏" aria-label="Permalink to &quot;🐍 巳（sì）· 阴火 · 四月 · 孟夏&quot;">​</a></h4><p>【字形】象蛇盘曲，有收藏之意<br> 【原文】&quot;巳者，言阳气之已尽也。&quot;（《史记·律书》）<br> 【状态】阳气上升到极致，阴气开始萌生，转折点</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>巳 = 立夏时节</span></span>
<span class="line"><span>  = 阳气最盛的起点，但一阴已生</span></span>
<span class="line"><span>  = 表面是热烈，内部已有收敛之机</span></span>
<span class="line"><span>  = 巳时（9–11点）= 上午最热烈的时段</span></span></code></pre></div><p>巳是火的长生地——火在巳月开始进入旺盛期。</p><h4 id="🔥-午-wu-·-阳火-·-五月-·-仲夏" tabindex="-1">🔥 午（wǔ）· 阳火 · 五月 · 仲夏 <a class="header-anchor" href="#🔥-午-wu-·-阳火-·-五月-·-仲夏" aria-label="Permalink to &quot;🔥 午（wǔ）· 阳火 · 五月 · 仲夏&quot;">​</a></h4><p>【字形】象杵臼，有冲击之意；又象阴阳交叉<br> 【原文】&quot;午者，阴阳交，故曰午。&quot;（《史记·律书》）<br> 【状态】阴阳在此正式交接——阳气极盛，阴气开始上升</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>午 = 夏至时节</span></span>
<span class="line"><span>  = 一年中阳气最盛的顶点，同时一阴生</span></span>
<span class="line"><span>  = 正午烈日，但已过顶点</span></span>
<span class="line"><span>  = 午时（11–13点）= 一天中最热的时段，也是阳气开始下降的转折</span></span></code></pre></div><p>午是火的旺地（帝旺），也是水的绝地——水火对冲，是地支中阴阳转换最剧烈的节点。</p><h4 id="🌾-未-wei-·-阴土-·-六月-·-季夏" tabindex="-1">🌾 未（wèi）· 阴土 · 六月 · 季夏 <a class="header-anchor" href="#🌾-未-wei-·-阴土-·-六月-·-季夏" aria-label="Permalink to &quot;🌾 未（wèi）· 阴土 · 六月 · 季夏&quot;">​</a></h4><p>【字形】象木有枝叶繁茂，果实已成<br> 【原文】&quot;未者，言万物皆成，有滋味也。&quot;（《史记·律书》）<br> 【状态】万物成熟有味，夏末丰收前的饱满状态</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>未 = 小暑大暑时节</span></span>
<span class="line"><span>  = 果实饱满，滋味最浓</span></span>
<span class="line"><span>  = 未土 = 燥土，夏末的干热之土</span></span>
<span class="line"><span>  = 成熟但尚未收割，最丰盛的等待</span></span></code></pre></div><p>未是四库之一，是木的墓库——夏末的燥土，封存着木的能量。</p><h4 id="🐒-申-shen-·-阳金-·-七月-·-孟秋" tabindex="-1">🐒 申（shēn）· 阳金 · 七月 · 孟秋 <a class="header-anchor" href="#🐒-申-shen-·-阳金-·-七月-·-孟秋" aria-label="Permalink to &quot;🐒 申（shēn）· 阳金 · 七月 · 孟秋&quot;">​</a></h4><p>【字形】象闪电之形，有伸展贯通之意<br> 【原文】&quot;申者，言阴用事，申贼万物，故曰申。&quot;（《史记·律书》）<br> 【状态】阴气开始主事，肃杀之气开始侵蚀万物</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>申 = 立秋时节</span></span>
<span class="line"><span>  = 秋风初起，肃杀之气开始</span></span>
<span class="line"><span>  = 申时（15–17点）= 下午阳光开始西斜，暑气渐退</span></span>
<span class="line"><span>  = 变革·决断·开始收割</span></span></code></pre></div><p>申是水的长生地——金生水，申月水开始萌生。</p><h4 id="🐔-酉-you-·-阴金-·-八月-·-仲秋" tabindex="-1">🐔 酉（yǒu）· 阴金 · 八月 · 仲秋 <a class="header-anchor" href="#🐔-酉-you-·-阴金-·-八月-·-仲秋" aria-label="Permalink to &quot;🐔 酉（yǒu）· 阴金 · 八月 · 仲秋&quot;">​</a></h4><p>【字形】象酒坛，有收藏精华之意<br> 【原文】&quot;酉者，万物之老也，故曰酉。&quot;（《史记·律书》）<br> 【状态】万物老熟收藏，精华内敛，秋收完成</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>酉 = 秋分时节</span></span>
<span class="line"><span>  = 昼夜再次等长，万物收藏</span></span>
<span class="line"><span>  = 酉时（17–19点）= 日落，一天的收尾</span></span>
<span class="line"><span>  = 精炼·收敛·成熟之极</span></span></code></pre></div><p>酉是金的旺地（帝旺）——金在酉月达到最旺状态。</p><h4 id="🐕-戌-xu-·-阳土-·-九月-·-季秋" tabindex="-1">🐕 戌（xū）· 阳土 · 九月 · 季秋 <a class="header-anchor" href="#🐕-戌-xu-·-阳土-·-九月-·-季秋" aria-label="Permalink to &quot;🐕 戌（xū）· 阳土 · 九月 · 季秋&quot;">​</a></h4><p>【字形】从&quot;戊&quot;从&quot;一&quot;，有戍守之意<br> 【原文】&quot;戌者，言万物尽灭，故曰戌。&quot;（《史记·律书》）<br> 【状态】万物趋于消灭，秋末肃杀，归于沉寂</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>戌 = 寒露霜降时节</span></span>
<span class="line"><span>  = 草木凋零，万物归藏</span></span>
<span class="line"><span>  = 戌时（19–21点）= 夜幕降临，活动收束</span></span>
<span class="line"><span>  = 守护·终结·为下一个循环清场</span></span></code></pre></div><p>戌是四库之一，是火的墓库——秋末的燥土，封存着火的能量。</p><h4 id="🐗-亥-hai-·-阴水-·-十月-·-孟冬" tabindex="-1">🐗 亥（hài）· 阴水 · 十月 · 孟冬 <a class="header-anchor" href="#🐗-亥-hai-·-阴水-·-十月-·-孟冬" aria-label="Permalink to &quot;🐗 亥（hài）· 阴水 · 十月 · 孟冬&quot;">​</a></h4><p>【字形】象猪之形，有藏纳之意<br> 【原文】&quot;亥者，该也，言阳气藏于下，故该也。&quot;（《史记·律书》）<br> 【状态】阳气完全潜藏于地下，外表是极寒，内部是下一个循环的种子</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>亥 = 立冬时节</span></span>
<span class="line"><span>  = 万物入冬，阳气深藏</span></span>
<span class="line"><span>  = 亥时（21–23点）= 深夜，万籁俱寂</span></span>
<span class="line"><span>  = 终结即是开始，亥之后就是子（新的循环）</span></span></code></pre></div><p>亥是木的长生地——水生木，亥月木开始萌生，为来年寅月的破土做准备。</p><hr><h3 id="_3-3-十二生肖-地支的文化面孔" tabindex="-1">3.3 十二生肖：地支的文化面孔 <a class="header-anchor" href="#_3-3-十二生肖-地支的文化面孔" aria-label="Permalink to &quot;3.3 十二生肖：地支的文化面孔&quot;">​</a></h3><h4 id="生肖是什么" tabindex="-1">生肖是什么？ <a class="header-anchor" href="#生肖是什么" aria-label="Permalink to &quot;生肖是什么？&quot;">​</a></h4><p>十二生肖，是十二地支的&quot;民间面孔&quot;。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地支 = 学术符号（子丑寅卯……）</span></span>
<span class="line"><span>生肖 = 文化符号（鼠牛虎兔……）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两者一一对应，是同一套系统的两种表达方式：</span></span>
<span class="line"><span>  学者用地支，民间用生肖。</span></span></code></pre></div><p>生肖的作用，是让抽象的地支符号，变成普通人可以直觉感知的具体形象——<br> 不识字的农民不懂&quot;子水阳支&quot;，但他知道自己属鼠，知道鼠年是什么年。</p><h4 id="考古依据-生肖何时成型" tabindex="-1">考古依据：生肖何时成型？ <a class="header-anchor" href="#考古依据-生肖何时成型" aria-label="Permalink to &quot;考古依据：生肖何时成型？&quot;">​</a></h4><p>【文献】睡虎地秦简《日书》（约前217年，湖北云梦出土，1975年）</p><p>这是现存最早记载十二生肖与地支对应的实物文献，证明该体系在秦代已完全成型。</p><p>值得注意的是：秦简中的生肖对应，与今日略有差异（如&quot;午&quot;对应&quot;鹿&quot;而非&quot;马&quot;），说明生肖与地支的配对，经历了一个历史演化过程，在汉代前后才基本固定为今日版本。</p><h4 id="十二生肖完整对应" tabindex="-1">十二生肖完整对应 <a class="header-anchor" href="#十二生肖完整对应" aria-label="Permalink to &quot;十二生肖完整对应&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">地支</th><th style="text-align:center;">生肖</th><th style="text-align:center;">五行</th><th style="text-align:center;">阴阳</th><th style="text-align:left;">生肖象意</th></tr></thead><tbody><tr><td style="text-align:center;">子</td><td style="text-align:center;">鼠</td><td style="text-align:center;">水</td><td style="text-align:center;">阳</td><td style="text-align:left;">夜间最活跃，繁殖力强，象征子时的暗中涌动</td></tr><tr><td style="text-align:center;">丑</td><td style="text-align:center;">牛</td><td style="text-align:center;">土</td><td style="text-align:center;">阴</td><td style="text-align:left;">耕耘大地，力大而缓，象征丑土的厚重蓄势</td></tr><tr><td style="text-align:center;">寅</td><td style="text-align:center;">虎</td><td style="text-align:center;">木</td><td style="text-align:center;">阳</td><td style="text-align:left;">百兽之王，破晓出没，象征寅时的破土而出</td></tr><tr><td style="text-align:center;">卯</td><td style="text-align:center;">兔</td><td style="text-align:center;">木</td><td style="text-align:center;">阴</td><td style="text-align:left;">日出而动，温柔繁茂，象征卯时的日出生机</td></tr><tr><td style="text-align:center;">辰</td><td style="text-align:center;">龙</td><td style="text-align:center;">土</td><td style="text-align:center;">阳</td><td style="text-align:left;">行云布雨，震动天地，象征辰土的湿润生发</td></tr><tr><td style="text-align:center;">巳</td><td style="text-align:center;">蛇</td><td style="text-align:center;">火</td><td style="text-align:center;">阴</td><td style="text-align:left;">盘曲收敛，蜕变潜行，象征巳火的内敛转折</td></tr><tr><td style="text-align:center;">午</td><td style="text-align:center;">马</td><td style="text-align:center;">火</td><td style="text-align:center;">阳</td><td style="text-align:left;">正午奔腾，阳刚极盛，象征午火的顶点转折</td></tr><tr><td style="text-align:center;">未</td><td style="text-align:center;">羊</td><td style="text-align:center;">土</td><td style="text-align:center;">阴</td><td style="text-align:left;">温顺成群，草木丰茂，象征未土的成熟饱满</td></tr><tr><td style="text-align:center;">申</td><td style="text-align:center;">猴</td><td style="text-align:center;">金</td><td style="text-align:center;">阳</td><td style="text-align:left;">灵动变化，肃杀初起，象征申金的决断变革</td></tr><tr><td style="text-align:center;">酉</td><td style="text-align:center;">鸡</td><td style="text-align:center;">金</td><td style="text-align:center;">阴</td><td style="text-align:left;">日落报时，精华内敛，象征酉金的收藏精炼</td></tr><tr><td style="text-align:center;">戌</td><td style="text-align:center;">狗</td><td style="text-align:center;">土</td><td style="text-align:center;">阳</td><td style="text-align:left;">守夜护院，终结清场，象征戌土的归藏守护</td></tr><tr><td style="text-align:center;">亥</td><td style="text-align:center;">猪</td><td style="text-align:center;">水</td><td style="text-align:center;">阴</td><td style="text-align:left;">深藏蓄养，终而复始，象征亥水的潜藏待发</td></tr></tbody></table><h4 id="生肖动物的选择逻辑" tabindex="-1">生肖动物的选择逻辑 <a class="header-anchor" href="#生肖动物的选择逻辑" aria-label="Permalink to &quot;生肖动物的选择逻辑&quot;">​</a></h4><p>这是一个至今没有完全定论的问题，诚实说明：</p><p><strong>可解释的部分（天文与物候对应）：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>子鼠 · 午马 = 昼夜活动的极端代表</span></span>
<span class="line"><span>              鼠活跃于深夜子时，马奔腾于正午午时</span></span>
<span class="line"><span>              两者是一天中阴阳极点的象征</span></span>
<span class="line"><span></span></span>
<span class="line"><span>卯兔 · 酉鸡 = 日出日落的报时者</span></span>
<span class="line"><span>              兔在卯时（日出5–7点）出没</span></span>
<span class="line"><span>              鸡在酉时（日落17–19点）归巢报时</span></span>
<span class="line"><span></span></span>
<span class="line"><span>辰龙         = 龙为行云布雨之神，辰为湿土、春雨之月</span></span>
<span class="line"><span>              龙与辰月的农业意象高度吻合</span></span>
<span class="line"><span></span></span>
<span class="line"><span>寅虎         = 虎为百兽之王，寅时（凌晨3–5点）是虎出没的时段</span></span>
<span class="line"><span>              古代猎人的实际观察记录</span></span></code></pre></div><p><strong>尚无定论的部分：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>丑牛·未羊·申猴·巳蛇·亥猪</span></span>
<span class="line"><span>这几个生肖与地支的对应，</span></span>
<span class="line"><span>目前学界主流倾向于&quot;图腾崇拜融合说&quot;：</span></span>
<span class="line"><span>上古不同部落以不同动物为图腾，</span></span>
<span class="line"><span>各部落融合后，图腾动物被分配到对应的地支位置。</span></span></code></pre></div><blockquote><p>生肖与地支的对应，象征意义大于天文逻辑，是“文化积累”的结果。<br> 文化本身反映某种“真实”。<br> 更多的考证与发现，留待后人探索。</p></blockquote><h3 id="_3-4-十二时辰-一天的十二段编码" tabindex="-1">3.4 十二时辰：一天的十二段编码 <a class="header-anchor" href="#_3-4-十二时辰-一天的十二段编码" aria-label="Permalink to &quot;3.4 十二时辰：一天的十二段编码&quot;">​</a></h3><h4 id="什么是十二时辰" tabindex="-1">什么是十二时辰？ <a class="header-anchor" href="#什么是十二时辰" aria-label="Permalink to &quot;什么是十二时辰？&quot;">​</a></h4><p>十二时辰，是古人将一天（24小时）划分为十二段的时间系统，每段对应一个地支，每段时长两小时。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1个时辰 = 2小时</span></span>
<span class="line"><span>12个时辰 = 24小时 = 1天</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这是地支&quot;纪时&quot;功能的直接体现：</span></span>
<span class="line"><span>同一套地支符号，既用于纪年、纪月，也用于纪时。</span></span></code></pre></div><p>【文献依据】《周礼》已有十二时辰制度的雏形；</p><p>《淮南子·天文训》有完整的十二时辰与地支对应记载；汉代以后成为官方标准时间制度，沿用至清末。</p><h4 id="十二时辰完整表" tabindex="-1">十二时辰完整表 <a class="header-anchor" href="#十二时辰完整表" aria-label="Permalink to &quot;十二时辰完整表&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">时辰</th><th style="text-align:center;">地支</th><th style="text-align:center;">现代时间</th><th style="text-align:center;">别名</th><th style="text-align:left;">自然状态</th></tr></thead><tbody><tr><td style="text-align:center;">子时</td><td style="text-align:center;">子</td><td style="text-align:center;">23:00–01:00</td><td style="text-align:center;">夜半</td><td style="text-align:left;">深夜最静，一阳初生，万籁俱寂</td></tr><tr><td style="text-align:center;">丑时</td><td style="text-align:center;">丑</td><td style="text-align:center;">01:00–03:00</td><td style="text-align:center;">鸡鸣</td><td style="text-align:left;">黎明前最深的黑暗，鸡尚未鸣</td></tr><tr><td style="text-align:center;">寅时</td><td style="text-align:center;">寅</td><td style="text-align:center;">03:00–05:00</td><td style="text-align:center;">平旦</td><td style="text-align:left;">黎明破晓前，天色微明</td></tr><tr><td style="text-align:center;">卯时</td><td style="text-align:center;">卯</td><td style="text-align:center;">05:00–07:00</td><td style="text-align:center;">日出</td><td style="text-align:left;">太阳升起，万物开始活动</td></tr><tr><td style="text-align:center;">辰时</td><td style="text-align:center;">辰</td><td style="text-align:center;">07:00–09:00</td><td style="text-align:center;">食时</td><td style="text-align:left;">早饭时间，一天活动全面展开</td></tr><tr><td style="text-align:center;">巳时</td><td style="text-align:center;">巳</td><td style="text-align:center;">09:00–11:00</td><td style="text-align:center;">隅中</td><td style="text-align:left;">上午最活跃的时段，阳气上升</td></tr><tr><td style="text-align:center;">午时</td><td style="text-align:center;">午</td><td style="text-align:center;">11:00–13:00</td><td style="text-align:center;">日中</td><td style="text-align:left;">正午，阳气顶点，日影最短</td></tr><tr><td style="text-align:center;">未时</td><td style="text-align:center;">未</td><td style="text-align:center;">13:00–15:00</td><td style="text-align:center;">日昳</td><td style="text-align:left;">日过中天，开始西斜</td></tr><tr><td style="text-align:center;">申时</td><td style="text-align:center;">申</td><td style="text-align:center;">15:00–17:00</td><td style="text-align:center;">晡时</td><td style="text-align:left;">下午，古代第二次进食时间</td></tr><tr><td style="text-align:center;">酉时</td><td style="text-align:center;">酉</td><td style="text-align:center;">17:00–19:00</td><td style="text-align:center;">日入</td><td style="text-align:left;">日落，收工归家</td></tr><tr><td style="text-align:center;">戌时</td><td style="text-align:center;">戌</td><td style="text-align:center;">19:00–21:00</td><td style="text-align:center;">黄昏</td><td style="text-align:left;">夜幕降临，点灯时分</td></tr><tr><td style="text-align:center;">亥时</td><td style="text-align:center;">亥</td><td style="text-align:center;">21:00–23:00</td><td style="text-align:center;">人定</td><td style="text-align:left;">夜深人静，万物归息</td></tr></tbody></table><p>【说明】以上时间为<strong>地方真太阳时</strong>，非北京标准时间。实际应用中需根据出生地经度换算。</p><h4 id="重要概念-夜子时与早子时" tabindex="-1">重要概念：夜子时与早子时 <a class="header-anchor" href="#重要概念-夜子时与早子时" aria-label="Permalink to &quot;重要概念：夜子时与早子时&quot;">​</a></h4><p>这是初学者最容易混淆的问题，也是术数实战中的重要细节。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>子时横跨两个自然日：</span></span>
<span class="line"><span>  23:00–24:00 = 当日的&quot;夜子时&quot;（属当日）</span></span>
<span class="line"><span>  00:00–01:00 = 次日的&quot;早子时&quot;（属次日）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题：23:30出生，算当天的子时，还是次日的子时？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两种流派：</span></span>
<span class="line"><span>  ① 以23:00为界（子时起即换日）</span></span>
<span class="line"><span>     → 23:30出生 = 次日子时</span></span>
<span class="line"><span>     → 此为多数命理师采用的标准</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ② 以00:00为界（自然日换日）</span></span>
<span class="line"><span>     → 23:30出生 = 当日亥时之后、次日子时之前</span></span>
<span class="line"><span>     → 此为部分流派的做法</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【实战建议】以所用体系为准，保持内部一致即可。</span></span>
<span class="line"><span>若无特别说明，本知识库采用&quot;子时起即换日&quot;标准。</span></span></code></pre></div><h4 id="时辰与现代时间的换算" tabindex="-1">时辰与现代时间的换算 <a class="header-anchor" href="#时辰与现代时间的换算" aria-label="Permalink to &quot;时辰与现代时间的换算&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标准换算（以北京时间为基准，东经116°）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>北京标准时间 - 地方经度修正 = 地方真太阳时</span></span>
<span class="line"><span></span></span>
<span class="line"><span>修正公式：</span></span>
<span class="line"><span>  每偏离东经120°一度，修正4分钟</span></span>
<span class="line"><span>  偏西则减，偏东则加</span></span>
<span class="line"><span></span></span>
<span class="line"><span>举例：</span></span>
<span class="line"><span>  出生地：成都（东经104°）</span></span>
<span class="line"><span>  偏西16°，修正 = 16 × 4 = 64分钟</span></span>
<span class="line"><span>  北京时间14:30 → 地方真太阳时 = 13:26</span></span>
<span class="line"><span>  → 实际时辰为未时（13:00–15:00），无误</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  出生地：上海（东经121°）</span></span>
<span class="line"><span>  偏东1°，修正 = 1 × 4 = 4分钟</span></span>
<span class="line"><span>  北京时间14:30 → 地方真太阳时 = 14:34</span></span>
<span class="line"><span>  → 仍为未时，无影响</span></span></code></pre></div><blockquote><p>时辰换算在四柱八字中影响时柱，进而影响整个命盘。<br> 出生地偏差较大时（如新疆、云南），换算尤为重要。</p></blockquote><h2 id="四、地支的核心结构-四组三元" tabindex="-1">四、地支的核心结构：四组三元 <a class="header-anchor" href="#四、地支的核心结构-四组三元" aria-label="Permalink to &quot;四、地支的核心结构：四组三元&quot;">​</a></h2><p>十二地支不是随机排列，有严密的内部结构。</p><h3 id="_4-1-四季三元-最重要的分组" tabindex="-1">4.1 四季三元（最重要的分组） <a class="header-anchor" href="#_4-1-四季三元-最重要的分组" aria-label="Permalink to &quot;4.1 四季三元（最重要的分组）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>春（木）：寅 → 卯 → 辰</span></span>
<span class="line"><span>         孟春  仲春  季春</span></span>
<span class="line"><span>         生    旺    墓</span></span>
<span class="line"><span></span></span>
<span class="line"><span>夏（火）：巳 → 午 → 未</span></span>
<span class="line"><span>         孟夏  仲夏  季夏</span></span>
<span class="line"><span>         生    旺    墓</span></span>
<span class="line"><span></span></span>
<span class="line"><span>秋（金）：申 → 酉 → 戌</span></span>
<span class="line"><span>         孟秋  仲秋  季秋</span></span>
<span class="line"><span>         生    旺    墓</span></span>
<span class="line"><span></span></span>
<span class="line"><span>冬（水）：亥 → 子 → 丑</span></span>
<span class="line"><span>         孟冬  仲冬  季冬</span></span>
<span class="line"><span>         生    旺    墓</span></span></code></pre></div><p>每一季的三个地支，对应该五行的&quot;生·旺·墓&quot;三个阶段：</p><table tabindex="0"><thead><tr><th style="text-align:left;">阶段</th><th style="text-align:left;">含义</th><th style="text-align:left;">类比</th></tr></thead><tbody><tr><td style="text-align:left;">生（孟月）</td><td style="text-align:left;">该五行开始萌生</td><td style="text-align:left;">种子入土</td></tr><tr><td style="text-align:left;">旺（仲月）</td><td style="text-align:left;">该五行达到极盛</td><td style="text-align:left;">花开正艳</td></tr><tr><td style="text-align:left;">墓（季月）</td><td style="text-align:left;">该五行收藏入库</td><td style="text-align:left;">果实入仓</td></tr></tbody></table><p>这就是四库（辰戌丑未）的来源——每季最后一个月，是该季主气的墓库。</p><h3 id="_4-2-四正-子午卯酉" tabindex="-1">4.2 四正（子午卯酉） <a class="header-anchor" href="#_4-2-四正-子午卯酉" aria-label="Permalink to &quot;4.2 四正（子午卯酉）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>子（正北·水旺）</span></span>
<span class="line"><span>午（正南·火旺）</span></span>
<span class="line"><span>卯（正东·木旺）</span></span>
<span class="line"><span>酉（正西·金旺）</span></span></code></pre></div><p>四正地支对应四个方位的极点，也是各五行的帝旺之地（能量最强处）。<br> 在奇门遁甲中，四正对应四门（休·生·伤·杜·景·死·惊·开中的正方位门）。</p><h3 id="_4-3-四库-辰戌丑未" tabindex="-1">4.3 四库（辰戌丑未） <a class="header-anchor" href="#_4-3-四库-辰戌丑未" aria-label="Permalink to &quot;4.3 四库（辰戌丑未）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>辰（东南·水库）</span></span>
<span class="line"><span>未（西南·木库）</span></span>
<span class="line"><span>戌（西北·火库）</span></span>
<span class="line"><span>丑（东北·金库）</span></span></code></pre></div><p>四库是四个过渡方位，每个都是某种五行能量的&quot;仓库&quot;。</p><p>【重要】四库的五行归属，初学者常混淆：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>● 辰是水库（不是木库，虽然辰在春季）</span></span>
<span class="line"><span>● 未是木库（不是火库，虽然未在夏季）</span></span>
<span class="line"><span>● 戌是火库（不是金库，虽然戌在秋季）</span></span>
<span class="line"><span>● 丑是金库（不是水库，虽然丑在冬季）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规律：每季末月，收藏的是上一季的主气，而非本季主气。</span></span></code></pre></div><h2 id="五、藏干-地支内部藏着什么" tabindex="-1">五、藏干：地支内部藏着什么？ <a class="header-anchor" href="#五、藏干-地支内部藏着什么" aria-label="Permalink to &quot;五、藏干：地支内部藏着什么？&quot;">​</a></h2><p>这是十二地支中最复杂、也最有价值的部分。</p><h3 id="_5-1-什么是藏干" tabindex="-1">5.1 什么是藏干？ <a class="header-anchor" href="#_5-1-什么是藏干" aria-label="Permalink to &quot;5.1 什么是藏干？&quot;">​</a></h3><p>每个地支内部，都&quot;藏&quot;着一到三个天干。<br> 这些天干代表该地支内部包含的五行能量。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>类比：</span></span>
<span class="line"><span>地支 = 一个房间</span></span>
<span class="line"><span>藏干 = 房间里住着的人（天干）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有的房间只住一个人（单纯）</span></span>
<span class="line"><span>有的房间住三个人（复杂）</span></span></code></pre></div><h3 id="_5-2-十二地支藏干完整表" tabindex="-1">5.2 十二地支藏干完整表 <a class="header-anchor" href="#_5-2-十二地支藏干完整表" aria-label="Permalink to &quot;5.2 十二地支藏干完整表&quot;">​</a></h3><p>依据《三命通会》（万民英，明代）标准版本：</p><table tabindex="0"><thead><tr><th style="text-align:center;">地支</th><th style="text-align:center;">本气（主）</th><th style="text-align:center;">中气（次）</th><th style="text-align:center;">余气（辅）</th></tr></thead><tbody><tr><td style="text-align:center;">子</td><td style="text-align:center;">癸（水）</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">丑</td><td style="text-align:center;">己（土）</td><td style="text-align:center;">癸（水）</td><td style="text-align:center;">辛（金）</td></tr><tr><td style="text-align:center;">寅</td><td style="text-align:center;">甲（木）</td><td style="text-align:center;">丙（火）</td><td style="text-align:center;">戊（土）</td></tr><tr><td style="text-align:center;">卯</td><td style="text-align:center;">乙（木）</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">辰</td><td style="text-align:center;">戊（土）</td><td style="text-align:center;">乙（木）</td><td style="text-align:center;">癸（水）</td></tr><tr><td style="text-align:center;">巳</td><td style="text-align:center;">丙（火）</td><td style="text-align:center;">庚（金）</td><td style="text-align:center;">戊（土）</td></tr><tr><td style="text-align:center;">午</td><td style="text-align:center;">丁（火）</td><td style="text-align:center;">己（土）</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">未</td><td style="text-align:center;">己（土）</td><td style="text-align:center;">丁（火）</td><td style="text-align:center;">乙（木）</td></tr><tr><td style="text-align:center;">申</td><td style="text-align:center;">庚（金）</td><td style="text-align:center;">壬（水）</td><td style="text-align:center;">戊（土）</td></tr><tr><td style="text-align:center;">酉</td><td style="text-align:center;">辛（金）</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">戌</td><td style="text-align:center;">戊（土）</td><td style="text-align:center;">辛（金）</td><td style="text-align:center;">丁（火）</td></tr><tr><td style="text-align:center;">亥</td><td style="text-align:center;">壬（水）</td><td style="text-align:center;">甲（木）</td><td style="text-align:center;">—</td></tr></tbody></table><p>【版本说明】藏干体系历代略有差异，以《三命通会》为主流标准。<br> 《渊海子平》与《滴天髓》个别地支藏干有出入，实战以所用体系为准。</p><h3 id="_5-3-藏干的三个层次" tabindex="-1">5.3 藏干的三个层次 <a class="header-anchor" href="#_5-3-藏干的三个层次" aria-label="Permalink to &quot;5.3 藏干的三个层次&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本气（司令之气）= 该地支最主要的五行，力量最强</span></span>
<span class="line"><span>中气（中间之气）= 次要五行，力量居中</span></span>
<span class="line"><span>余气（初气）    = 最弱的五行，但仍有影响</span></span>
<span class="line"><span></span></span>
<span class="line"><span>力量比例参考（以寅为例）：</span></span>
<span class="line"><span>寅藏：甲（本气·约70%）· 丙（中气·约20%）· 戊（余气·约10%）</span></span></code></pre></div><h3 id="_5-4-为什么要有藏干" tabindex="-1">5.4 为什么要有藏干？ <a class="header-anchor" href="#_5-4-为什么要有藏干" aria-label="Permalink to &quot;5.4 为什么要有藏干？&quot;">​</a></h3><p>如果地支只有一个五行，世界就太简单了。<br> 现实中，每个时间段、每个空间，都同时包含多种能量，只是主次不同。</p><p>藏干，就是对这种&quot;复合能量状态&quot;的精确描述。</p><h4 id="举例" tabindex="-1">举例： <a class="header-anchor" href="#举例" aria-label="Permalink to &quot;举例：&quot;">​</a></h4><p>寅月（正月）= 表面是木（甲木当令）</p><p>但内部还藏着：</p><ul><li>丙火（春天的阳光，温暖已在积累）</li><li>戊土（大地的承载，根系在扎深）</li></ul><p>所以寅月不只是&quot;木旺&quot;，而是&quot;木主导，火在孕育，土在承载&quot;的复合状态。</p><p>这就是为什么同样是&quot;木旺&quot;的寅月和卯月，在术数应用中会有细微差别——卯只藏乙木，单纯；寅藏甲丙戊，复杂。</p><h2 id="六、地支六冲-为什么正对面的地支会-冲" tabindex="-1">六、地支六冲：为什么正对面的地支会&quot;冲&quot;？ <a class="header-anchor" href="#六、地支六冲-为什么正对面的地支会-冲" aria-label="Permalink to &quot;六、地支六冲：为什么正对面的地支会&quot;冲&quot;？&quot;">​</a></h2><h3 id="_6-1-六冲列表" tabindex="-1">6.1 六冲列表 <a class="header-anchor" href="#_6-1-六冲列表" aria-label="Permalink to &quot;6.1 六冲列表&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>子 ↔ 午（水火相冲）</span></span>
<span class="line"><span>丑 ↔ 未（土土相冲）</span></span>
<span class="line"><span>寅 ↔ 申（木金相冲）</span></span>
<span class="line"><span>卯 ↔ 酉（木金相冲）</span></span>
<span class="line"><span>辰 ↔ 戌（土土相冲）</span></span>
<span class="line"><span>巳 ↔ 亥（火水相冲）</span></span></code></pre></div><h3 id="_6-2-冲的本质" tabindex="-1">6.2 冲的本质 <a class="header-anchor" href="#_6-2-冲的本质" aria-label="Permalink to &quot;6.2 冲的本质&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>十二地支排成一圈（以时钟12点为午，6点为子）</span></span>
<span class="line"><span>相隔六位 = 正对面 = 方位相反 = 五行相克或同性相斥</span></span>
<span class="line"><span></span></span>
<span class="line"><span>子午：正北↔正南，水↔火，阴阳极点相冲</span></span>
<span class="line"><span>卯酉：正东↔正西，木↔金，春秋相冲</span></span>
<span class="line"><span>寅申：东北↔西南，木↔金，生克相冲</span></span>
<span class="line"><span>巳亥：东南↔西北，火↔水，生克相冲</span></span>
<span class="line"><span>辰戌：东南↔西北，土↔土，同性相斥</span></span>
<span class="line"><span>丑未：东北↔西南，土↔土，同性相斥</span></span></code></pre></div><p>冲的作用：</p><ul><li><strong>冲动（激活）</strong>：沉寂的地支被冲，会激发其藏干的能量</li><li><strong>冲破（破坏）</strong>：稳定的结构被冲，会造成动荡</li><li><strong>冲开库</strong>：四库（辰戌丑未）被冲，藏干中的能量得以释放</li></ul><h2 id="七、地支六合-日月相会的天文配对" tabindex="-1">七、地支六合：日月相会的天文配对 <a class="header-anchor" href="#七、地支六合-日月相会的天文配对" aria-label="Permalink to &quot;七、地支六合：日月相会的天文配对&quot;">​</a></h2><h3 id="_7-1-六合列表" tabindex="-1">7.1 六合列表 <a class="header-anchor" href="#_7-1-六合列表" aria-label="Permalink to &quot;7.1 六合列表&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>子 + 丑 = 合化土</span></span>
<span class="line"><span>寅 + 亥 = 合化木</span></span>
<span class="line"><span>卯 + 戌 = 合化火</span></span>
<span class="line"><span>辰 + 酉 = 合化金</span></span>
<span class="line"><span>巳 + 申 = 合化水</span></span>
<span class="line"><span>午 + 未 = 合化火土</span></span></code></pre></div><h3 id="_7-2-六合的真实来源-日月相会" tabindex="-1">7.2 六合的真实来源：日月相会 <a class="header-anchor" href="#_7-2-六合的真实来源-日月相会" aria-label="Permalink to &quot;7.2 六合的真实来源：日月相会&quot;">​</a></h3><p>古人观测发现：太阳每月运行到某个地支方位（月建），月亮会在与之对应的另一个地支方位与太阳相会（即朔，农历初一）。这个固定的配对关系，就是六合的天文来源。</p><p>以月建（太阳所在位置）为基准，日月相会的配对：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正月 （寅月）= 太阳在寅，月亮在亥与之相会 → 寅亥合</span></span>
<span class="line"><span>二月 （卯月）= 太阳在卯，月亮在戌与之相会 → 卯戌合</span></span>
<span class="line"><span>三月 （辰月）= 太阳在辰，月亮在酉与之相会 → 辰酉合</span></span>
<span class="line"><span>四月 （巳月）= 太阳在巳，月亮在申与之相会 → 巳申合</span></span>
<span class="line"><span>五月 （午月）= 太阳在午，月亮在未与之相会 → 午未合</span></span>
<span class="line"><span>十一月（子月）= 太阳在子，月亮在丑与之相会 → 子丑合</span></span></code></pre></div><p>六合的本质，是日月相会的天文记录，是日月交会的固定配对。<br> 依据《淮南子·天文训》的月将体系，六合是日月交会在十二地支上的投影。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/png/314561/1784702987603-bbd77837-94c7-4303-9331-87c7987b0b6f.png" alt=""></p><blockquote><p>子丑、午未 = 相邻两位</p><p>寅亥、卯戌、辰酉、巳申 = 跨越多位</p><p>记忆六合，最可靠的方法是<strong>记住天文来源</strong>（日月相会的月份配对）</p></blockquote><h3 id="_7-3-合化五行的来源" tabindex="-1">7.3 合化五行的来源 <a class="header-anchor" href="#_7-3-合化五行的来源" aria-label="Permalink to &quot;7.3 合化五行的来源&quot;">​</a></h3><p>每对六合，合化的五行来自两者共同激发的旺气：</p><table tabindex="0"><thead><tr><th style="text-align:left;">六合</th><th style="text-align:center;">合化</th><th style="text-align:left;">原因</th></tr></thead><tbody><tr><td style="text-align:left;">子 + 丑</td><td style="text-align:center;">土</td><td style="text-align:left;">子丑同处冬末，丑土当令，土气最旺</td></tr><tr><td style="text-align:left;">寅 + 亥</td><td style="text-align:center;">木</td><td style="text-align:left;">亥为木长生，寅为木旺地，木气汇聚</td></tr><tr><td style="text-align:left;">卯 + 戌</td><td style="text-align:center;">火</td><td style="text-align:left;">卯为木旺（木生火），戌为火墓（火归藏），火气流转</td></tr><tr><td style="text-align:left;">辰 + 酉</td><td style="text-align:center;">金</td><td style="text-align:left;">酉为金旺，辰为水库（金生水），金气主导</td></tr><tr><td style="text-align:left;">巳 + 申</td><td style="text-align:center;">水</td><td style="text-align:left;">申为水长生，巳中藏庚（金生水），水气汇聚</td></tr><tr><td style="text-align:left;">午 + 未</td><td style="text-align:center;">火土</td><td style="text-align:left;">午为火旺，未为火墓兼土旺，火土同气</td></tr></tbody></table><h2 id="八、地支三合-最重要的组合关系" tabindex="-1">八、地支三合：最重要的组合关系 <a class="header-anchor" href="#八、地支三合-最重要的组合关系" aria-label="Permalink to &quot;八、地支三合：最重要的组合关系&quot;">​</a></h2><h3 id="_8-1-三合列表" tabindex="-1">8.1 三合列表 <a class="header-anchor" href="#_8-1-三合列表" aria-label="Permalink to &quot;8.1 三合列表&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>申 + 子 + 辰 = 三合水局</span></span>
<span class="line"><span>亥 + 卯 + 未 = 三合木局</span></span>
<span class="line"><span>寅 + 午 + 戌 = 三合火局</span></span>
<span class="line"><span>巳 + 酉 + 丑 = 三合金局</span></span></code></pre></div><blockquote><p>简化记忆：子水，丑金，寅火，卯木记这 4 个，每一组，依次找 + 3，如：</p><p>水：子，（+3 丑寅卯）辰、（+3 巳午未）申，这样水局三合可推出，其他同理。</p></blockquote><h3 id="_8-2-三合的结构逻辑" tabindex="-1">8.2 三合的结构逻辑 <a class="header-anchor" href="#_8-2-三合的结构逻辑" aria-label="Permalink to &quot;8.2 三合的结构逻辑&quot;">​</a></h3><p>每个三合局，由生·旺·墓三个地支组成：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>水局：申（水长生）+ 子（水帝旺）+ 辰（水墓库）= 水的完整生命周期</span></span>
<span class="line"><span>木局：亥（木长生）+ 卯（木帝旺）+ 未（木墓库）= 木的完整生命周期</span></span>
<span class="line"><span>火局：寅（火长生）+ 午（火帝旺）+ 戌（火墓库）= 火的完整生命周期</span></span>
<span class="line"><span>金局：巳（金长生）+ 酉（金帝旺）+ 丑（金墓库）= 金的完整生命周期</span></span></code></pre></div><p>三合的力量远大于六合：<br> 三合是一个五行从出生到极盛到收藏的完整闭环，<br> 三个地支聚在一起，等于把这个五行的全部生命力量汇聚一处。</p><hr><h2 id="九、地支三会-方位的极致聚合" tabindex="-1">九、地支三会：方位的极致聚合 <a class="header-anchor" href="#九、地支三会-方位的极致聚合" aria-label="Permalink to &quot;九、地支三会：方位的极致聚合&quot;">​</a></h2><h3 id="_9-1-三会列表" tabindex="-1">9.1 三会列表 <a class="header-anchor" href="#_9-1-三会列表" aria-label="Permalink to &quot;9.1 三会列表&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>寅 + 卯 + 辰 = 三会东方木局（春季三月）</span></span>
<span class="line"><span>巳 + 午 + 未 = 三会南方火局（夏季三月）</span></span>
<span class="line"><span>申 + 酉 + 戌 = 三会西方金局（秋季三月）</span></span>
<span class="line"><span>亥 + 子 + 丑 = 三会北方水局（冬季三月）</span></span></code></pre></div><h3 id="_9-2-三会与三合的区别" tabindex="-1">9.2 三会与三合的区别 <a class="header-anchor" href="#_9-2-三会与三合的区别" aria-label="Permalink to &quot;9.2 三会与三合的区别&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三合 = 同一五行的生旺墓聚合（跨季节，力量完整）</span></span>
<span class="line"><span>三会 = 同一季节的三个月聚合（同方位，力量纯粹）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三会的力量 &gt; 三合的力量</span></span>
<span class="line"><span>（因为三会是同方位、同季节、同五行的三重叠加）</span></span></code></pre></div><hr><h2 id="十、与各术数体系的接口" tabindex="-1">十、与各术数体系的接口 <a class="header-anchor" href="#十、与各术数体系的接口" aria-label="Permalink to &quot;十、与各术数体系的接口&quot;">​</a></h2><h3 id="_10-1-四柱八字" tabindex="-1">10.1 四柱八字 <a class="header-anchor" href="#_10-1-四柱八字" aria-label="Permalink to &quot;10.1 四柱八字&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地支 = 八字中&quot;地&quot;的层面</span></span>
<span class="line"><span>    → 年支·月支·日支·时支</span></span>
<span class="line"><span>    → 月支 = 最重要（当令之气，决定整体格局）</span></span>
<span class="line"><span>    → 日支 = 配偶宫（婚姻感情的主要参考）</span></span>
<span class="line"><span>    → 藏干 = 八字信息量的主要来源</span></span></code></pre></div><h3 id="_10-2-奇门遁甲" tabindex="-1">10.2 奇门遁甲 <a class="header-anchor" href="#_10-2-奇门遁甲" aria-label="Permalink to &quot;10.2 奇门遁甲&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地支 = 时间定局的基础</span></span>
<span class="line"><span>    → 由节气、天干地支，决定起局的参数</span></span>
<span class="line"><span>    → 地支五行影响各宫的旺衰判断</span></span>
<span class="line"><span>    → 地支冲合影响格局的动静</span></span></code></pre></div><h3 id="_10-3-六爻-纳甲" tabindex="-1">10.3 六爻（纳甲） <a class="header-anchor" href="#_10-3-六爻-纳甲" aria-label="Permalink to &quot;10.3 六爻（纳甲）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地支 = 六爻的核心操作对象</span></span>
<span class="line"><span>    → 六爻每一爻都对应一个地支</span></span>
<span class="line"><span>    → 地支的冲合刑害 = 爻与爻之间的关系</span></span>
<span class="line"><span>    → 月建（当月地支）和日辰（当日地支）= 判断爻的旺衰的标准</span></span></code></pre></div><h3 id="_10-4-大六壬" tabindex="-1">10.4 大六壬 <a class="header-anchor" href="#_10-4-大六壬" aria-label="Permalink to &quot;10.4 大六壬&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地支 = 十二将的基础</span></span>
<span class="line"><span>    → 十二天将分配于十二地支</span></span>
<span class="line"><span>    → 月将（太阳所在宫位）+ 占时地支 = 起课的核心</span></span></code></pre></div><hr><h2 id="十一、现代解读-地支本质上是什么" tabindex="-1">十一、现代解读：地支本质上是什么？ <a class="header-anchor" href="#十一、现代解读-地支本质上是什么" aria-label="Permalink to &quot;十一、现代解读：地支本质上是什么？&quot;">​</a></h2><h3 id="_11-1-时空容器的十二种状态" tabindex="-1">11.1 时空容器的十二种状态 <a class="header-anchor" href="#_11-1-时空容器的十二种状态" aria-label="Permalink to &quot;11.1 时空容器的十二种状态&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果天干是&quot;能量的性质&quot;</span></span>
<span class="line"><span>那地支就是&quot;能量所在的容器&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>容器不同，同样的能量，表现出来的效果也不同：</span></span>
<span class="line"><span>  同样是&quot;木&quot;的能量</span></span>
<span class="line"><span>  在寅（阳木·初生）= 破土而出，锐不可当</span></span>
<span class="line"><span>  在卯（阴木·极旺）= 枝繁叶茂，生机盎然</span></span>
<span class="line"><span>  在辰（木入库）   = 收敛入土，准备转化</span></span></code></pre></div><h3 id="_11-2-为什么是12-不是10" tabindex="-1">11.2 为什么是12，不是10？ <a class="header-anchor" href="#_11-2-为什么是12-不是10" aria-label="Permalink to &quot;11.2 为什么是12，不是10？&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天干是10（对应十月太阳历）</span></span>
<span class="line"><span>地支是12（对应十二月阴历）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>12 的来源：</span></span>
<span class="line"><span>  木星公转周期 ≈ 11.86年 ≈ 12年</span></span>
<span class="line"><span>  → 每年木星移动约一个&quot;宫位&quot;</span></span>
<span class="line"><span>  → 12个宫位 = 12地支</span></span>
<span class="line"><span></span></span>
<span class="line"><span>同时：</span></span>
<span class="line"><span>  一年12个月（阴历）</span></span>
<span class="line"><span>  一天12个时辰</span></span>
<span class="line"><span>  → 12是月亮周期与木星周期的共同因子</span></span></code></pre></div><p>这解释了为什么十二地支能同时用于纪年·纪月·纪日·纪时——<br> 因为它本身就来自多个天文周期的最大公约数。</p><hr><h2 id="十二、承前启后" tabindex="-1">十二、承前启后 <a class="header-anchor" href="#十二、承前启后" aria-label="Permalink to &quot;十二、承前启后&quot;">​</a></h2><p><strong>上承：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  十天干（天干地支，天地配合）</span></span>
<span class="line"><span>  五行论（地支五行归属的哲学来源）</span></span>
<span class="line"><span>  二十八星宿（月亮轨道是地支的天文基础）</span></span></code></pre></div><p><strong>本篇建立：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  十二地支 = 时间坐标系的第二维</span></span>
<span class="line"><span>           = 时空容器的十二种状态</span></span>
<span class="line"><span>           = 藏干体系（复合能量的精确描述）</span></span>
<span class="line"><span>           = 十二生肖（地支的文化面孔）</span></span>
<span class="line"><span>           = 十二时辰（地支的日内编码）</span></span>
<span class="line"><span>           = 冲合三合三会的基础</span></span></code></pre></div><p><strong>下启：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  → 13·六十甲子（天干+地支=完整时间编码）</span></span>
<span class="line"><span>  → 15·历法体系（月建·朔望·阴阳合历的完整背景）</span></span>
<span class="line"><span>  → 16·十二长生（地支与五行能量周期的精细化）</span></span>
<span class="line"><span>  → 27·地支藏干（专项深化）</span></span>
<span class="line"><span>  → 六爻纳甲（地支是六爻的核心操作对象）</span></span></code></pre></div><hr><h2 id="十三、本章小结" tabindex="-1">十三、本章小结 <a class="header-anchor" href="#十三、本章小结" aria-label="Permalink to &quot;十三、本章小结&quot;">​</a></h2><p>十二地支，是古人对月亮轨道与地球季节周期的十二段精确编码。</p><p><strong>五重价值：</strong></p><ol><li>📅 <strong>历法价值</strong>：纪年·纪月·纪日·纪时，四维时间坐标</li><li>🌱 <strong>物候价值</strong>：每个地支对应真实的自然状态，是古代农业文明的时间智慧</li><li>🐯 <strong>文化价值</strong>：十二生肖是地支的民间面孔，是中华文化最广泛的符号系统之一</li><li>🔮 <strong>术数价值</strong>：藏干·冲合·三合·三会，构成所有术数体系的时间操作基础</li><li>🧠 <strong>思维价值</strong>：复合能量模型（藏干），是理解&quot;表象与内在&quot;关系的思维工具</li></ol><p>学地支，有两个层次：</p><p><strong>第一层</strong>：记住每个地支的五行·方位·时辰·月份·生肖。这是工具层，必须熟练。</p><p><strong>第二层</strong>：理解每个地支描述的那个自然状态。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>子是冬至地下的涌动，午是夏至正午的转折，</span></span>
<span class="line"><span>寅是破土而出的第一声，酉是秋收入仓的满足，</span></span>
<span class="line"><span>丑是冻土中蓄势待发的种子，亥是深冬里潜藏的新生……</span></span></code></pre></div><p>第二层才是根。有了根，第一层自然记得住，切勿本末倒置。</p><hr><p>下一篇预告：<strong>13 · 六十甲子</strong>——天干与地支的完整结合，60年一轮回的时间编码，以及&quot;黄帝命大挠作甲子&quot;背后的历史真相。</p><hr><p>文档版本：v1.2 · 十二地支 ｜ 2026年7月<br> 更新说明：新增3.3十二生肖专节、3.4十二时辰专节；原11.3生肖内容并入3.3；承前启后序号对应新计划表更新</p><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3>`,223)])])}const u=a(l,[["render",p]]);export{g as __pageData,u as default};
